cd /tmp/main-edit && git fetch -q origin && git merge --ff-only -q origin/main; python3 - <<'PY'
import re,os,yaml,glob
bad=[]
nums={}
for p in sorted(glob.glob('/tmp/main-edit/S*/E*.md'), key=lambda x:(int(x[-6:-4]),int(x[-3:-1]))):
    txt=open(p,encoding='utf-8').read()
    rel=p.replace('/tmp/main-edit/','')
    m=re.match(r'^---\n(.*?)\n---\n\n(.*?)\n\n',txt,re.S)
    if not m: bad.append((rel,'no frontmatter')); continue
    fm=m.group(1); intro=m.group(2)
    try: d=yaml.safe_load(fm)
    except Exception as e: bad.append((rel,'yaml: '+str(e))); continue
    for k in ['title','summary','season','episode','status']:
        if k not in d: bad.append((rel,'missing '+k))
    if 'summary' in d and d['summary']!=intro: bad.append((rel,'summary != intro'))
    if 'summary' in d:
        w=len(str(d['summary']).split())
        if w<15 or w>45: bad.append((rel,f'summary words {w}'))
    if not str(d.get('title','')).startswith('The One With'): bad.append((rel,'title style'))
    n=len(re.findall(r'^Source: friend/',txt,re.M))
    nums[rel]=n
print("files:",len(nums))
print("total utterances:",sum(nums.values()))
for b in bad: print("ISSUE:",b)
print("--- last few counts ---")
for k in list(nums)[-6:]: print(k,nums[k])
